/// Concatenate two vectors by copying all elements of `v1` followed by all elements of `v2`.
/// 
/// Post-conditions:
/// - The returned `Vec` has length `v1.len() + v2.len()`.
/// - For 0 <= i < v1.len(), result[i] == v1[i].
/// - For v1.len() <= i < result.len(), result[i] == v2[i - v1.len()].
pub fn append_vectors<T: Copy>(v1: &Vec<T>, v2: &Vec<T>) -> Vec<T> {
    // Precompute the total length and allocate once.
    let total_len = v1.len() + v2.len();
    let mut result = Vec::with_capacity(total_len);

    // Extend by copying elements of v1, then of v2.
    result.extend(v1.iter().copied());
    result.extend(v2.iter().copied());

    result
}

/// Given two integer vectors, `first` (non-empty) and `second`, produce a new vector
/// consisting of all elements of `first` except its last, followed by all elements of `second`.
///
/// Post-conditions:
/// - The returned Vec has length `(first.len() - 1) + second.len()`.
/// - For 0 <= i < first.len() - 1, result[i] == first[i].
/// - For first.len() - 1 <= i < result.len(), result[i] == second[i - (first.len() - 1)]`.
pub fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> Vec<i32> {
    // We assume `first` is non-empty.
    assert!(!first.is_empty(), "`first` must have at least one element");

    let prefix_len = first.len() - 1;
    let mut result = Vec::with_capacity(prefix_len + second.len());

    // Copy all but the last of `first`.
    result.extend(first.iter().take(prefix_len).copied());
    // Then copy all of `second`.
    result.extend(second.iter().copied());

    result
}

